                            if (nr, nc) not in visited and result[nr][nc] == result[cr][cc]:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                # Apply square frame fill
                color = result[comp[0][0]][comp[0][1]]
                if len(comp) < 4:
